mapper.select:
SELECT t.id AS taskId, t.shop_id AS shopId, COALESCE(s.poi_name, s.name) AS shopName, s.poi_id AS poiId, s.epoi_id AS epoiId, t.trigger_date AS triggerDate, t.plan_time AS planTime, t.content, t.week_days AS weekDays, t.repeat_mode AS repeatMode, t.status, t.target_count AS targetCount, t.truncated_count AS truncatedCount, t.shard_count AS shardCount, t.success_count AS successCount, t.fail_count AS failCount, t.skip_reason AS skipReason, t.planned_at AS plannedAt, t.started_at AS startedAt, t.finished_at AS finishedAt, t.create_time AS createTime FROM mt_im_broadcast_task t JOIN mt_shop s ON s.id = t.shop_id
AND t.shop_id = #{shopId}
AND (s.name LIKE CONCAT('%', #{shopKeyword}, '%') OR s.poi_name LIKE CONCAT('%', #{shopKeyword}, '%') OR s.poi_id LIKE CONCAT('%', #{shopKeyword}, '%') OR s.epoi_id LIKE CONCAT('%', #{shopKeyword}, '%'))
AND t.status = #{status} AND t.repeat_mode = #{repeatMode}
AND t.content LIKE CONCAT('%', #{contentKeyword}, '%')
AND t.create_time >= #{startTime} AND t.create_time <= #{endTime}
ORDER BY t.create_time DESC, t.id DESC
